sys_script.script:
(function executeRule(current, previous) {

    var item = current.getValue('item_used');   // inventory sys_id
    var qtyUsed = parseInt(current.getValue('quantity_used'), 10);

    // Stop if data missing
    if (!item || !qtyUsed) {
        return;
    }

    var inv = new GlideRecord('x_1896972_smart_0_inventory');

    // Fetch inventory record
    if (inv.get(item)) {

        gs.info(' Inventory record found');

        var available = parseInt(inv.getValue('quantity_available'), 10);
        var remaining = available - qtyUsed;

        // Update quantity
        inv.setValue('quantity_available', remaining);

        // ✅ Update status
        if (remaining <= 0) {
            inv.setValue('status', 'out_of_stock');
        }
        else if (remaining <= 10) {
            inv.setValue('status', 'low_stock');
        }
        else {
            inv.setValue('status', 'available');
        }

        // 🔴 IMPORTANT: only ONE update()
        inv.update();

        gs.info(' Inventory quantity & status updated successfully');
    }
    else {
        gs.info(' Inventory record NOT found');
    }

})(current, previous);
